-- Source observations supplement an existing stable asset identity; no duplicate catalogue.
CREATE TABLE asset_metadata_observations(id uuid PRIMARY KEY,asset_id text NOT NULL REFERENCES asset_catalog_entries(id),owner_id text NOT NULL REFERENCES users(id),source_page_id uuid NOT NULL,target_id text NOT NULL,target_fingerprint text NOT NULL,license_revision text NOT NULL,source_action text NOT NULL CHECK(source_action IN ('sync','backfill')),board text,market_cap numeric CHECK(market_cap IS NULL OR market_cap>=0),market_cap_currency text,source_as_of timestamptz,observed_at timestamptz NOT NULL,request_id uuid NOT NULL,UNIQUE(asset_id,owner_id,source_page_id),FOREIGN KEY(owner_id,source_page_id) REFERENCES asset_source_pages(owner_id,id));
CREATE INDEX asset_metadata_latest ON asset_metadata_observations(asset_id,observed_at DESC,id DESC);
CREATE TRIGGER retain_asset_metadata_observation BEFORE UPDATE OR DELETE ON asset_metadata_observations FOR EACH ROW EXECUTE FUNCTION immutable_trade_ledger();
